let questions=[];
const $=id=>document.getElementById(id);let index=0,attempts=0,solved=false,busy=false,mode='demo',connected=false;
function render(){const q=questions[index];$('counter').textContent=`봉인 ${index+1} / ${questions.length}`;$('attempts').textContent=`도전 ${attempts}회`;$('seals').replaceChildren(...questions.map((_,i)=>{let e=document.createElement('span');e.textContent=i<index?'✓':i+1;e.className=i<index?'done':i===index?'active':'';return e}));$('room').textContent=q.room;$('title').textContent=q.title;$('clue').textContent=q.clue;$('question').textContent=q.q;$('hint').textContent=q.hint;$('hint').hidden=true;$('hintBtn').hidden=false;$('feedback').textContent='';$('feedback').className='';$('next').hidden=true;$('choices').replaceChildren(...q.options.map((t,i)=>{let b=document.createElement('button');b.textContent=`${i+1}. ${t}`;b.onclick=()=>answer(i,b);return b}));}
async function api(path,body){if(!['127.0.0.1','localhost'].includes(location.hostname))throw Error('실행 꾸러미를 내려받아 bridge.py가 제공하는 로컬 페이지를 열어 주세요.');const r=await fetch(path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined,signal:AbortSignal.timeout(path==='/api/connect'?20000:6000)});const d=await r.json();if(!r.ok)throw Error(d.error||'연결 프로그램 응답 오류');return d;}
async function answer(choice,button){if(busy||solved)return;if(mode==='robot'&&!connected){$('feedback').textContent='먼저 햄스터 연결을 확인해 주세요.';return}busy=true;document.querySelectorAll('[name=mode]').forEach(r=>r.disabled=true);attempts++;$('attempts').textContent=`도전 ${attempts}회`;let result;try{result=await api('/api/answer',{session:sessionId,choice})}catch(e){busy=false;document.querySelectorAll('[name=mode]').forEach(r=>r.disabled=false);$('feedback').textContent=e.message;return}const ok=result.correct;document.querySelectorAll('#choices button').forEach(b=>b.disabled=true);button.className=ok?'correct':'wrong';$('lamp').className=ok?'green':'red';$('motion').textContent=ok?'정답 · 앞뒤로 이동':'오답 · 좌우로 회전';$('motion').className=ok?'right-motion':'wrong-motion';let robotError='';try{if(mode==='robot')await api('/api/feedback',{correct:ok});else await new Promise(r=>setTimeout(r,1500));}catch(e){connected=false;robotError=` 교구 반응 실패: ${e.message}`;$('connection').textContent='연결을 다시 확인해 주세요.'}finally{busy=false;document.querySelectorAll('[name=mode]').forEach(r=>r.disabled=false);$('motion').className='';}
 $('feedback').className=ok?'success':'error';if(ok){solved=true;$('feedback').textContent=`봉인이 풀렸습니다. ${result.explain}${robotError}`;let a=document.createElement('a');a.href=questions[index].source;a.textContent=' 학습 자료';a.target='_blank';a.rel='noreferrer';$('feedback').append(a);$('next').textContent=index===questions.length-1?'기록실 탈출하기':'다음 봉인으로';$('next').hidden=false;}else{$('feedback').textContent=`아직 봉인이 풀리지 않았습니다. 단서를 읽고 다시 도전하세요.${robotError}`;document.querySelectorAll('#choices button').forEach(b=>b.disabled=false);}}
$('next').onclick=async()=>{if(busy)return;busy=true;try{await api('/api/advance',{session:sessionId})}catch(e){$('feedback').textContent=e.message;busy=false;return}busy=false;if(index<questions.length-1){index++;solved=false;render()}else{$('counter').textContent=`봉인 ${questions.length} / ${questions.length} · 탈출 성공`;$('seals').querySelectorAll('span').forEach(e=>e.className='done');$('room').textContent='MISSION COMPLETE';$('title').textContent='자유의 문이 열렸습니다!';$('clue').textContent='모든 기록을 되찾았습니다. 혁명의 기록을 다음 세대에 전해 주세요.';$('question').textContent=`총 ${attempts}번의 도전으로 모든 봉인을 풀었습니다.`;$('choices').replaceChildren();$('hintBtn').hidden=true;$('hint').hidden=true;$('feedback').textContent='삼부회 → 국민의회 → 바스티유 습격 → 인권선언 → 입헌군주제 → 공화정. 자유와 평등을 향한 변화의 흐름을 기억해 주세요.';$('next').hidden=true;}};
$('hintBtn').onclick=async()=>{try{await api('/api/hint',{session:sessionId});$('hint').hidden=!$('hint').hidden}catch(e){$('feedback').textContent=e.message}};$('help').onclick=()=>$('guide').showModal();$('closeGuide').onclick=()=>$('guide').close();
document.querySelectorAll('[name=mode]').forEach(r=>r.onchange=()=>{mode=r.value;connected=false;$('connection').textContent=mode==='demo'?'체험 모드 · 화면에서 반응을 확인합니다.':'햄스터 모드 · 연결 확인이 필요합니다.'});
$('connect').onclick=async()=>{if(busy)return;const button=$('connect');button.disabled=true;button.textContent='햄스터 연결 중…';$('connection').textContent='USB 동글과 햄스터 응답을 확인하고 있습니다.';try{const d=await api('/api/connect',{});connected=d.connected;if(!connected)throw Error('햄스터 연결을 확인하지 못했습니다.');mode='robot';document.querySelectorAll('[name=mode]').forEach(r=>r.checked=r.value==='robot');$('connection').textContent=`햄스터 연결 완료 · ${d.port||'USB 동글'} · 정답과 오답에 교구가 반응합니다.`;button.textContent='햄스터 다시 연결';}catch(e){connected=false;$('connection').textContent=e.message;button.textContent='햄스터 연결';}finally{button.disabled=false;}};
$('stop').onclick=async()=>{try{if(mode==='robot')await api('/api/stop',{});$('lamp').className='';$('motion').className='';$('motion').textContent='정지 요청 완료';}catch(e){$('connection').textContent=e.message;}};

$('restart').onclick=()=>{if(busy)return;$('setup').hidden=false;$('playPanel').hidden=true;initialize();};
let sessionId='';
async function initialize(){try{const settings=await api('/api/config');$('recordOptions').hidden=!settings.recording;$('startGame').disabled=false;}catch(e){$('setupStatus').textContent='서버 연결 실패: '+e.message;}}
$('startGame').onclick=async()=>{if(busy)return;busy=true;$('startGame').disabled=true;try{const d=await api('/api/start',{team:$('team').value,opt_in:$('optIn').checked});questions=d.questions;sessionId=d.session;index=0;attempts=0;solved=false;$('setup').hidden=true;$('playPanel').hidden=false;$('recordStatus').textContent=d.recording?'학습 기록을 저장합니다.':'학습 기록을 저장하지 않습니다.';render();}catch(e){$('setupStatus').textContent=e.message;}finally{busy=false;$('startGame').disabled=false;}};
document.addEventListener('visibilitychange',()=>{if(document.hidden&&mode==='robot')navigator.sendBeacon('/api/stop',new Blob(['{}'],{type:'application/json'}))});initialize();
